from pathlib import Path
P=Path('public')
def edit(file,old,new):
 f=P/file;s=f.read_text()
 if new in s:return
 if s.count(old)!=1:raise RuntimeError(f'{file}: expected 1 anchor, found {s.count(old)}')
 f.write_text(s.replace(old,new,1));print('Updated',file)
notice='<div class="notice">Uses MTPLM and MIRO from your caravan profile. Check the manufacturer\'s MIRO definition: fitted extras, gas, water and other items may or may not already be included. Weigh your loaded caravan to confirm actual weight. Nose weight and tow vehicle limits require separate checks.</div>'
edit('index.html',notice,'')
old='<details class="payload-safety-info"><summary aria-label="Payload safety information" title="Payload safety information">ⓘ</summary><div class="payload-safety-popover">Uses MTPLM and MIRO from your caravan profile. Check the manufacturer\'s MIRO definition: fitted extras, gas, water and other items may or may not already be included. Weigh your loaded caravan to confirm actual weight. Nose weight and tow vehicle limits require separate checks.</div></details>'
edit('index.html',old,'<button type="button" id="payloadSafetyTrigger" class="payload-safety-trigger" aria-haspopup="dialog" aria-controls="payloadSafetyDialog" aria-label="Payload safety information">ⓘ</button>')
dialog='<dialog id="payloadSafetyDialog" class="payload-safety-dialog" aria-labelledby="payloadSafetyTitle"><div class="payload-safety-dialog-head"><h2 id="payloadSafetyTitle">Payload safety information</h2><button type="button" id="payloadSafetyClose" class="secondary" aria-label="Close safety information">✕</button></div><p>Uses MTPLM and MIRO from your caravan profile. Check the manufacturer\'s MIRO definition: fitted extras, gas, water and other items may or may not already be included.</p><p>Weigh your loaded caravan to confirm actual weight. Nose weight and tow vehicle limits require separate checks.</p><button type="button" id="payloadSafetyDone">Close</button></dialog>'
edit('index.html','<dialog id="serviceDialog">',dialog+'<dialog id="serviceDialog">')
